160  /** 从磁盘读取并校验配置，错误信息不含 YAML 原文。 */
161  function readConfig(file: string): ConfigSnapshot {
162    //M 启动和重读共用同一份入口校验。
163    const yamlText = fs.readFileSync(file, 'utf8');
164    const document = yaml.parseDocument(yamlText);
165  
166    //G YAML 解析错误会带出原文，错误里只保留行号。
167    const broken = document.errors[0];
168    if (broken !== undefined) {
169      const line = String(broken.linePos?.[0].line ?? '?');
170      throw new Error(`config.yaml 不是合法的 YAML（第 ${line} 行附近）`);
171    }
172  
173    const written: unknown = document.toJSON();
174    //M 交给 checkConfig 校验一次。顶层确认是对象后，插件仍可读取原始值。
175    const config = checks.checkConfig(written);
176    const raw = written as Record<string, unknown>;
177    return { config, raw };
178  }
179  
180  
```

### 解释
- L163：读 config.yaml 原文。
- L167–L171：守卫：YAML 解析错误会带出原文，错误里只保留行号。
- L175：**外部入口**：交给 checkConfig 校验一次，之后内部直接用。
- L177：校验后的配置和原始对象一起交回。

