297    /** 监听 config.yaml，合并保存动作产生的多次文件通知。 */
298    private watchConfig(file: string): void {
299      this.ctx.effect(() => {
300        let pending: ReturnType<typeof setTimeout> | undefined;
301        //M 非持久监听与定时器让命令行模式能照常退出。
302        const watcher = fs.watch(this.root, { persistent: false }, (_event, name) => {
303          if (name !== null && name.toLowerCase() !== CONFIG_FILE) return;
304  
305          clearTimeout(pending);
306          pending = setTimeout(() => this.reloadConfig(file), CONFIG_RELOAD_DELAY_MS);
307          pending.unref();
308        });
309        watcher.on('error', (error) => {
310          console.error(`config.yaml 监听失败：${error.message}`);
311        });
312        return () => {
313          clearTimeout(pending);
314          watcher.close();
315        };
316      });
317    }
318  
```

### 解释
- L302：监听父目录（设置页用临时文件原子替换后仍能继续监听）；非持久监听让命令行模式能照常退出。
- L303：守卫：不是 config.yaml 的改动不管。
- L306：防抖：500 毫秒后才调重读。
- L314：服务被拔掉时收掉监听和定时器。

